+};
+struct SystemErrorWhileLoadingExternalBlockFile {
+    std::string what;
+};
+struct SystemErrorWhileSavingBlock {
+    std::string what;
+};
+struct UndoDataWriteFailed {};
+struct UndoFileCloseFailed {};
